passages:
{"acquirer": [{"quote": "following the Domestication, Merger Sub will merge with and into PAD with PAD surviving the merger as a wholly owned subsidiary of FACT", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "target": [{"quote": "Precision Aerospace & Defense Group, Inc., a Florida corporation (“PAD”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "consideration_type": [{"quote": "each PAD Share that is issued and outstanding immediately prior to the Effective Time (other than any treasury shares and dissenting shares) will be automatically canceled and converted into the right to receive a number of Public Shares equal to 12,388,291 divided by the number of PAD Shares issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "cash_consideration": [], "stock_exchange_ratio": [{"quote": "each PAD Share that is issued and outstanding immediately prior to the Effective Time (other than any treasury shares and dissenting shares) will be automatically canceled and converted into the right to receive a number of Public Shares equal to 12,388,291 divided by the number of PAD Shares issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}, {"quote": "the FACT Class A Common Stock, as converted into common stock, par value $0.0001 per share, of FACT at the effective time of the Merger (the “Effective Time”), the “FACT Common Stock”, and, following consummation of the Merger, the “New PAD Common Stock”", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The Closing is conditioned upon the satisfaction or waiver by the applicable parties to the Business Combination Agreement of the conditions set forth below.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 99", "relevance_score": 5}, {"quote": "The obligation of the parties to consummate the Business Combination is conditioned upon the satisfaction or waiver of certain customary closing conditions by each of the parties, including among other things:
(i) The approval and adoption of the Business Combination Agreement, the Business Combination and other matters by the FACT Shareholders and the PAD Stockholders;
(ii) No Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any law (whether temporary, preliminary or permanent) or order, decree, ruling, judgment, injunction, writ, binding determination or decision, verdict or judicial award that is then in effect and that has the effect of making the Business Combination illegal or otherwise prohibiting, restraining or imposing any condition on the consummation of the Business Combination;
(iii) The Registration Statement shall have been declared effective in accordance with the provisions of the Securities Act, no stop order shall have been issued by the SEC that remains in effect with respect to the Registration Statement, and no proceeding seeking such a stop order shall have been threatened or initiated by the SEC and not withdrawn; and
(iv) (A) all applicable waiting periods under the HSR Act with respect to the Business Combination shall have expired or been terminated, (B) at least 60 days shall have elapsed since the submission to the United States Department of State Directorate of Defense Trade Controls of all information required by 22 C.F.R. § 122.4(b), and (C) each consent, approval, waiver, authorization, waiting period expiration or termination, or permit of, or notice to or declaration or filing with, any Governmental Authority required to consummate the Business Combination shall have been obtained and shall be in full force and effect.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 99", "relevance_score": 5}, {"quote": "The obligations of PAD to consummate the Business Combination are subject to additional conditions, including, among others: (i) the truth and accuracy of the representations and warranties of FACT and Merger Sub, subject to customary bring-down standards; (ii) material compliance by FACT and Merger Sub with their respective obligations, agreements and covenants under the Business Combination Agreement; (iii) receipt by PAD of a closing certificate of FACT; (iv) there being no Material Adverse Effect (as defined in the Business Combination Agreement) with respect to FACT; (v) FACT having provided the Public Shareholders the opportunity to make redemption elections with respect to their FACT Class A Shares; (vi) FACT’s initial listing application in connection with the Business Combination shall have been conditionally approved and, immediately following the Effective Time, FACT shall satisfy any applicable initial listing requirements of Nasdaq; (vii) the aggregate cash available from the Trust Account and other sources as set forth in the Business Combination Agreement equaling no less than $75,000,000 (after deducting SPAC Transaction Expenses (as defined in the Business Combination Agreement) and any amounts paid to FACT Shareholders that exercise their redemption rights in connection with the Business Combination); (viii) receipt of certain executed ancillary documents and the amended and restated certificate of incorporation of FACT shall have become effective; and (ix) FACT having taken all necessary and appropriate measures to have all funds held in the Trust Account be disbursed to FACT and released from the Trust Account to New PAD on the Closing Date.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 4", "relevance_score": 5}, {"quote": "The obligations of FACT and Merger Sub to consummate the Business Combination are subject to additional conditions, including, among other things: (i) the truth and accuracy of the representations and warranties of PAD, subject to customary bring-down standards; (ii) material compliance by PAD with its agreements and covenants under the Business Combination Agreement; (iii) no Material Adverse Effect (as defined in the Business Combination Agreement) with respect to PAD having occurred since the date of the Business Combination Agreement that is continuing; and (iv) receipt of a closing certificate of PAD and certain executed ancillary documents.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 4", "relevance_score": 5}], "event_status": [{"quote": "It is currently expected that the Business Combination will be consummated in the second quarter of 2026.", "location": "S-4, Questions and Answers About the Business Combination, page xxviii", "relevance_score": 5}], "security_description": [{"quote": "each share of common stock of PAD, par value $0.001 per share (“PAD Shares”) that is issued and outstanding immediately prior to the Effective Time", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "each PAD Share that is issued and outstanding immediately prior to the Effective Time (other than any treasury shares and dissenting shares) will be automatically canceled and converted into the right to receive a number of Public Shares equal to 12,388,291 divided by the number of PAD Shares issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "default_option": [], "election_deadline": [], "merger_subsidiary": [{"quote": "Patriot Merger Subsidiary, Inc., a Florida corporation and wholly-owned subsidiary of FACT (“Merger Sub”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "cash_consideration_qualifications": [], "stock_exchange_ratio_type": [{"quote": "a number of Public Shares equal to 12,388,291 divided by the number of PAD Shares issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "each PAD Share that is issued and outstanding immediately prior to the Effective Time (other than any treasury shares and dissenting shares)", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}, {"quote": "each Person who would otherwise be entitled to a fraction of a SPAC Share (after aggregating all fractional SPAC Shares that would otherwise be received by such Person) shall instead have the number SPAC Shares issued to such Person rounded up to the nearest whole SPAC Share.", "location": "S-4, Annex A, Business Combination Agreement, Section 1.17, page A-9", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "It is currently expected that the Business Combination will be consummated in the second quarter of 2026.", "location": "S-4, Questions and Answers About the Business Combination, page xxviii", "relevance_score": 5}], "event_status_details": [{"quote": "On November 26, 2025, FACT entered into the Business Combination Agreement with Sponsor HoldCo, Merger Sub and PAD.", "location": "S-4, Proposal No. 1 — The Business Combination Proposal, page 64", "relevance_score": 5}, {"quote": "As of the date of this proxy statement/prospectus, the Minimum FACT Cash Amount has not been satisfied.", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}]}

{"acquirer": [{"quote": "following the Domestication, Merger Sub will merge with and into PAD with PAD surviving the merger as a wholly owned subsidiary of FACT", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "target": [{"quote": "Precision Aerospace & Defense Group, Inc., a Florida corporation (“PAD”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "consideration_type": [{"quote": "each share of PAD Series A Preferred Stock (other than the treasury and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of the PAD Series A Preferred Stock, and (B) a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, PAD Series B Preferred Stock and PAD Series C Preferred Stock issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "cash_consideration": [{"quote": "each share of PAD Series A Preferred Stock (other than the treasury and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of the PAD Series A Preferred Stock, and (B) a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, PAD Series B Preferred Stock and PAD Series C Preferred Stock issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, PAD Series B Preferred Stock and PAD Series C Preferred Stock issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}, {"quote": "the FACT Class A Common Stock, as converted into common stock, par value $0.0001 per share, of FACT at the effective time of the Merger (the “Effective Time”), the “FACT Common Stock”, and, following consummation of the Merger, the “New PAD Common Stock”", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The Closing is conditioned upon the satisfaction or waiver by the applicable parties to the Business Combination Agreement of the conditions set forth below.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 99", "relevance_score": 5}, {"quote": "The obligation of the parties to consummate the Business Combination is conditioned upon the satisfaction or waiver of certain customary closing conditions by each of the parties, including among other things:
(i) The approval and adoption of the Business Combination Agreement, the Business Combination and other matters by the FACT Shareholders and the PAD Stockholders;
(ii) No Governmental Authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any law (whether temporary, preliminary or permanent) or order, decree, ruling, judgment, injunction, writ, binding determination or decision, verdict or judicial award that is then in effect and that has the effect of making the Business Combination illegal or otherwise prohibiting, restraining or imposing any condition on the consummation of the Business Combination;
(iii) The Registration Statement shall have been declared effective in accordance with the provisions of the Securities Act, no stop order shall have been issued by the SEC that remains in effect with respect to the Registration Statement, and no proceeding seeking such a stop order shall have been threatened or initiated by the SEC and not withdrawn; and
(iv) (A) all applicable waiting periods under the HSR Act with respect to the Business Combination shall have expired or been terminated, (B) at least 60 days shall have elapsed since the submission to the United States Department of State Directorate of Defense Trade Controls of all information required by 22 C.F.R. § 122.4(b), and (C) each consent, approval, waiver, authorization, waiting period expiration or termination, or permit of, or notice to or declaration or filing with, any Governmental Authority required to consummate the Business Combination shall have been obtained and shall be in full force and effect.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 99", "relevance_score": 5}, {"quote": "The obligations of PAD to consummate the Business Combination are subject to additional conditions, including, among others: (i) the truth and accuracy of the representations and warranties of FACT and Merger Sub, subject to customary bring-down standards; (ii) material compliance by FACT and Merger Sub with their respective obligations, agreements and covenants under the Business Combination Agreement; (iii) receipt by PAD of a closing certificate of FACT; (iv) there being no Material Adverse Effect (as defined in the Business Combination Agreement) with respect to FACT; (v) FACT having provided the Public Shareholders the opportunity to make redemption elections with respect to their FACT Class A Shares; (vi) FACT’s initial listing application in connection with the Business Combination shall have been conditionally approved and, immediately following the Effective Time, FACT shall satisfy any applicable initial listing requirements of Nasdaq; (vii) the aggregate cash available from the Trust Account and other sources as set forth in the Business Combination Agreement equaling no less than $75,000,000 (after deducting SPAC Transaction Expenses (as defined in the Business Combination Agreement) and any amounts paid to FACT Shareholders that exercise their redemption rights in connection with the Business Combination); (viii) receipt of certain executed ancillary documents and the amended and restated certificate of incorporation of FACT shall have become effective; and (ix) FACT having taken all necessary and appropriate measures to have all funds held in the Trust Account be disbursed to FACT and released from the Trust Account to New PAD on the Closing Date.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 4", "relevance_score": 5}, {"quote": "The obligations of FACT and Merger Sub to consummate the Business Combination are subject to additional conditions, including, among other things: (i) the truth and accuracy of the representations and warranties of PAD, subject to customary bring-down standards; (ii) material compliance by PAD with its agreements and covenants under the Business Combination Agreement; (iii) no Material Adverse Effect (as defined in the Business Combination Agreement) with respect to PAD having occurred since the date of the Business Combination Agreement that is continuing; and (iv) receipt of a closing certificate of PAD and certain executed ancillary documents.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 4", "relevance_score": 5}], "event_status": [{"quote": "It is currently expected that the Business Combination will be consummated in the second quarter of 2026.", "location": "S-4, Questions and Answers About the Business Combination, page xxviii", "relevance_score": 5}], "security_description": [{"quote": "each share of Series A Preferred Stock of PAD, par value $0.001 per share (the “PAD Series A Preferred Stock”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "effective_date": [], "available_options": [{"quote": "each share of PAD Series A Preferred Stock (other than the treasury and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of the PAD Series A Preferred Stock, and (B) a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, PAD Series B Preferred Stock and PAD Series C Preferred Stock issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "default_option": [], "election_deadline": [], "merger_subsidiary": [{"quote": "Patriot Merger Subsidiary, Inc., a Florida corporation and wholly-owned subsidiary of FACT (“Merger Sub”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "cash_consideration_qualifications": [{"quote": "with respect to each share of PAD Preferred Stock, $5.00 cash and an amount in cash equal to all dividends on such share of PAD Preferred Stock that are due and unpaid as of the Effective Time.", "location": "S-4, Questions and Answers About the Business Combination, page xvii", "relevance_score": 5}, {"quote": "the holder of a Company Share or share of Company Preferred Stock that was converted pursuant to Section 1.6(b) into the right to receive the Per Share Common Merger Consideration or the Per Share Preferred Merger Consideration shall be entitled to receive, subject to any required withholding Taxes, the Per Share Common Merger Consideration or the Per Share Preferred Merger Consideration in book-entry form, without interest (subject to any applicable withholding Tax), and, with respect to each share of Company Preferred Stock, a check in the amount of (i) $5.00, without interest, representing its pro rata share of the Preferred Stock Cash Payment plus (ii) any dividends due on such share of Company Preferred Stock as of the Merger Effective Time pursuant to the applicable Certificate of Designations for such share of Company Preferred Stock, for each Company Share or share of Company Preferred Stock, as applicable, surrendered.", "location": "S-4, Annex A, Business Combination Agreement, Section 1.12(c), page A-7", "relevance_score": 5}], "stock_exchange_ratio_type": [{"quote": "a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, PAD Series B Preferred Stock and PAD Series C Preferred Stock issued and outstanding immediately prior to the Effective Time", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "stock_exchange_ratio_qualifications": [{"quote": "each share of PAD Series A Preferred Stock (other than the treasury and dissenting shares)", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}, {"quote": "each Person who would otherwise be entitled to a fraction of a SPAC Share (after aggregating all fractional SPAC Shares that would otherwise be received by such Person) shall instead have the number SPAC Shares issued to such Person rounded up to the nearest whole SPAC Share.", "location": "S-4, Annex A, Business Combination Agreement, Section 1.17, page A-9", "relevance_score": 5}], "other_consideration": [], "expected_closing": [{"quote": "It is currently expected that the Business Combination will be consummated in the second quarter of 2026.", "location": "S-4, Questions and Answers About the Business Combination, page xxviii", "relevance_score": 5}], "event_status_details": [{"quote": "On November 26, 2025, FACT entered into the Business Combination Agreement with Sponsor HoldCo, Merger Sub and PAD.", "location": "S-4, Proposal No. 1 — The Business Combination Proposal, page 64", "relevance_score": 5}, {"quote": "As of the date of this proxy statement/prospectus, the Minimum FACT Cash Amount has not been satisfied.", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}]}

{"acquirer": [{"quote": "following the Domestication, Merger Sub will merge with and into PAD with PAD surviving the merger as a wholly owned subsidiary of FACT", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "target": [{"quote": "Precision Aerospace & Defense Group, Inc., a Florida corporation (“PAD”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "consideration_type": [{"quote": "each share of PAD Series B Preferred Stock (other than any treasury shares and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of PAD Series B Preferred Stock, and (B) the Per Share Series A-C Preferred Stock Consideration", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "cash_consideration": [{"quote": "each share of PAD Series B Preferred Stock (other than any treasury shares and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of PAD Series B Preferred Stock, and (B) the Per Share Series A-C Preferred Stock Consideration", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "each share of PAD Series B Preferred Stock (other than any treasury shares and dissenting shares) that is issued and outstanding immediately prior to the Effective Time will be automatically canceled and converted into the right to receive (A) $5.00 in cash, which amount is equal to the original purchase price per share of PAD Series B Preferred Stock, and (B) the Per Share Series A-C Preferred Stock Consideration", "location": "S-4, The Business Combination Agreement — Merger Consideration, page 87", "relevance_score": 5}, {"quote": "a number of Public Shares equal to 621,500 divided by the number of shares of PAD Series A Preferred Stock, Series B Preferred Stock of PAD, par value $0.001 (the “PAD Series B Preferred Stock”), and Series C Preferred Stock of PAD, par value $0.001 per shares (the “PAD Series C Preferred Stock”) issued and outstanding immediately prior to the Effective Time (the “Per Share Series A-C Preferred Stock Consideration”)", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}, {"quote": "the FACT Class A Common Stock, as converted into common stock, par value $0.0001 per share, of FACT at the effective time of the Merger (the “Effective Time”), the “FACT Common Stock”, and, following consummation of the Merger, the “New PAD Common Stock”", "location": "S-4, preliminary proxy statement/prospectus", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The Closing is conditioned upon the satisfaction or waiver by the applicable parties to the Business Combination Agreement of the conditions set forth below.", "location": "S-4, The Business Combination Agreement — Closing Conditions, page 99", "relevance_score": 5}, {"quote": "The obligation of the parties to consummate the Business Combination is conditioned upon the satisfaction or waiver of certain customary closing conditions by each of the parties, including among other things:
